  if($versions&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($versions['id']);$body=json_body();$reason=sv_clean($body['reason']??'',500);if(!$id||mb_strlen($reason)<10)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'A change reason of at least 10 characters is required.'],400);$pdo=db();$pdo->beginTransaction();try{$c=sv104_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND'],404);}if(!sv104_policy((string)$c['Status'],(int)$c['CurrentVersionID'],(int)$c['CurrentVersionID'])['createRevisionAllowed']){$pdo->rollBack();json_response(['success'=>false,'code'=>'REVISION_NOT_ALLOWED'],409);}if(db_row("SELECT id FROM SafetyVote_CampaignVersions WHERE CampaignID=? AND Status='Draft' AND id<>? LIMIT 1 FOR UPDATE",[$id,$c['CurrentVersionID']])){$pdo->rollBack();json_response(['success'=>false,'code'=>'DRAFT_REVISION_EXISTS'],409);}$max=(int)(db_row('SELECT MAX(VersionNo) maxNo FROM SafetyVote_CampaignVersions WHERE CampaignID=? FOR UPDATE',[$id])['maxNo']??0);$stmt=$pdo->prepare("INSERT INTO SafetyVote_CampaignVersions(CampaignID,ParentVersionID,ChangeReason,VersionNo,ContractVersion,TemplateKey,CampaignType,PrivacyMode,TitleTh,TitleEn,Summary,Description,RulesText,TimeZone,OpenAt,CloseAt,ResultVisibility,EditPolicy,ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,PrivacyThreshold,AllowAbstain,RandomizeOptions,Status,CreatedBy,UpdatedBy) SELECT CampaignID,id,?,?,?,TemplateKey,CampaignType,PrivacyMode,TitleTh,TitleEn,Summary,Description,RulesText,TimeZone,OpenAt,CloseAt,ResultVisibility,'revision_required',ScoringMethod,ScoringConfigJson,TieBreakRule,QuorumRuleJson,PrivacyThreshold,AllowAbstain,RandomizeOptions,'Draft',?,? FROM SafetyVote_CampaignVersions WHERE id=?");$stmt->execute([$reason,$max+1,SAFETY_VOTE_PHASE104_CONTRACT,sv_actor($u),sv_actor($u),$c['CurrentVersionID']]);$vid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO SafetyVote_Sta