  if($media&&$method==='PUT'){sv_require_permission($u,'SAFETY_VOTE_MANAGE');$id=sv_positive_int($media['id']);$vid=sv_positive_int($media['versionId']);$parsed=sv104_media_list(json_body()['items']??null);if(!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','details'=>$parsed['errors']],400);$pdo=db();$pdo->beginTransaction();try{$c=sv104_campaign((int)$id,true);$v=sv104_version((int)$id,(int)$vid,true);if(!$c||!$v){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_NOT_FOUND'],404);}$policy=sv104_policy((string)$c['Status'],(int)$c['CurrentVersionID'],$vid);if($v['Status']!=='Draft'||(!$policy['directEditAllowed']&&!$policy['revisionEditAllowed'])){$pdo->rollBack();json_response(['success'=>false,'code'=>'LIVE_VERSION_IMMUTABLE'],409);}$codes=[];foreach(db_rows('SELECT QuestionCode FROM SafetyVote_Questions WHERE CampaignVersionID=?',[$vid])as$q)$codes[(string)$q['QuestionCode']]=true;foreach($parsed['items']as$x)if($x['questionCode']&&!isset($codes[$x['questionCode']])){$pdo->rollBack();json_response(['success'=>false,'code'=>'MEDIA_SCOPE_INVALID'],400);}$pdo->prepare('DELETE FROM SafetyVote_MediaLinks WHERE CampaignID=? AND CampaignVersionID=?')->execute([$id,$vid]);$stmt=$pdo->prepare('INSERT INTO SafetyVote_MediaLinks(CampaignID,CampaignVersionID,ScopeType,QuestionCode,OptionCode,MediaType,Provider,Url,EmbedUrl,Title,SortOrder,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($parsed['items']as$x)$stmt->execute([$id,$vid,$x['scopeType'],$x['questionCode'],$x['optionCode'],$x['mediaType'],$x['provider'],$x['url'],$x['embedUrl'],$x['title'],$x['sortOrder'],sv_actor($u),sv_actor($u)]);$pdo->commit();sv104_event($u,'SAFETY_VOTE_MEDIA_REPLACE',$id,$vid,'items='.count($parsed['items']),['serverFetch'=>false]);json_response(['success'=>true,'data'=>['items'=>$parsed['items'],'serverFetch'=>false,'autoEmbed'=>false]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
  if($activate&&$method==='POST'){sv_require_permission($u,'SAFETY_VOTE_ADMIN');$id=sv_positive_int($activate['id']);$vid=sv_positive_int($activate['versionId']);$body=json_body();$pdo=db();$pdo->beginTransaction();try{$c=sv104_campaign((int)$id,true);$v=sv104_version((int)$id,(int)$vid,true);if(!$c||!$v){$pdo->rollBack();json_response(['success'=>false,'code'=>'VERSION_NOT_FOUND'],404);}if(($body['confirmation']??'')!=='ACTIVATE '.$c['CampaignCode'].' V'.$v['VersionNo']){$pdo->rollBack();json_response(['success'=>false,'code'=>'ACTIVATION_CONFIRMATION_REQUIRED'],400);}$policy=sv104_policy((string)$c['Status'],(int)$c['CurrentVersionID'],$vid);if(!$policy['activateRevisionAllowed']||(int)$c['CurrentVersionID']===$vid||$v['Status']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'REVISION_ACTIVATION_BLOCKED'],409);}$ready=db_row("SELECT (SELECT COUNT(*) FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active') questions,(SELECT COUNT(*) FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1) rules",[$vid,$vid]);if(!(int)$ready['questions']||!(int)$ready['rules']){$pdo->rollBack();json_response(['success'=>false,'code'=>'REVISION_NOT_READY'],409);}$usage=db_row('SELECT (SELECT COUNT(*) FROM SafetyVote_Ballots WHERE CampaignVersionID=?) ballots,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=?) participation',[$vid,$vid]);if((int)$usage['ballots']||(int)$usage['participation']){$pdo->rollBack();json_response(['success'=>false,'code'=>'REVISION_HAS_BUSINESS_DATA'],409);}$pdo->prepare("UPDATE SafetyVote_Campaigns SET CurrentVersionID=?,Status='Draft',ScheduledOpenAt=?,ScheduledCloseAt=?,OpenedAt=NULL,ClosedAt=NULL,CertifiedAt=NULL,PublishedAt=NULL,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([$vid,$v['OpenAt'],$v['CloseAt'],sv_actor($u),$id]);$pdo->commit();sv104_event($u,'SAFETY_VOTE_VERSION_ACTIVATE',$id,$vid,'from='.$c['CurrentVersionID'].'; to='.$vid,['previousVersionId'=>(int)$c['CurrentVersionID'],'campaignReturnedToDraft'=>true]);json_response(['success'=>true,'data'=>['campaignId'=>$id,'currentVersionId'=>$vid,'previousVersionId'=>(int)$c['CurrentVersionID'],'status'=>'Draft','requiresFreshReadiness'=>true,'requiresFreshEligibilityFreeze'=>true]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
 }catch(Throwable$e){sv104_setup_error($e);}return false;
